    function banneh() {
        //console.log("banneh", $(window).width())
        if ($(window).width() > 750) {
            $("#inbanne").css("height", ($(window).height() - 90) + "px")
        } else {
            let width = $(window).width();
            //console.log("banneh", $(window).width())
            let s = width / 750;
            //console.log(s);
            let height = 1125 * s;
            $("#inbanne").css("height", (height) + "px")
        }
    }


